        with self.lock:
            data = {
                "users": {uid: asdict(u) for uid, u in self.users.items()},
                "projects": {pid: asdict(p) for pid, p in self.projects.items()},
                "tasks": {tid: asdict(t) for tid, t in self.tasks.items()},
                "messages": {mid: asdict(m) for mid, m in self.messages.items()},
            }
            with open(filename, "w") as f:
                json.dump(data, f, indent=2, default=str)

    def load_from_file(self, filename: str):
