@dataclass
class PerformanceMetrics:
    user_id: str
    total_tasks_assigned: int = 0
    completed_tasks: int = 0
    avg_completion_time_hours: float = 0.0
    feedback_ratings: List[float] = field(default_factory=list)

    def completion_rate(self) -> float:
        if self.total_tasks_assigned == 0:
            return 0.0
        return round((self.completed_tasks / self.total_tasks_assigned) * 100, 2)

# ============== Storage Layer (In-Memory + Thread Safety) ==============

class Storage:
    def __init__(self):
        self._lock = threading.RLock()
        self.users: Dict[str, User] = {}
        self.projects: Dict[str, Project] = {}
        self.tasks: Dict[str, Task] = {}
        self.messages: List[Message] = []
        self.performance: Dict[str, PerformanceMetrics] = {}
        self.attachments_dir = "./attachments"
        os.makedirs(self.attachments_dir, exist_ok=True)

    def _get_or_create_metrics(self, user_id: str) -> PerformanceMetrics:
        if user_id not in self.performance:
            self.performance[user_id] = PerformanceMetrics(user_id=user_id)
        return self.performance[user_id]

    def add_user(self, user: User):
        with self._lock:
            self.users[user.user_id] = user
            if user.user_id not in self.performance:
                self.performance[user.user_id] = PerformanceMetrics(user_id=user.user_id)

    def add_project(self, project: Project):
        with self._lock:
            self.projects[project.project_id] = project

    def add_task(self, task: Task):
        with self._lock:
            self.tasks[task.task_id] = task
            # Update metrics
            metrics = self._get_or_create_metrics(task.assignee_id)
            metrics.total_tasks_assigned += 1

    def update_task_status(self, task_id: str, new_status: TaskStatus):
        with self._lock:
            if task_id not in self.tasks:
                raise ValueError(f"Task {task_id} not found")
            task = self.tasks[task_id]
            if new_status == TaskStatus.COMPLETED and task.status != TaskStatus.COMPLETED:
                task.mark_completed()
                # Update metrics
                metrics = self._get_or_create_metrics(task.assignee_id)
                metrics.completed_tasks += 1
                # Compute completion time in hours
                if task.completed_at and task.created_at:
                    delta = (task.completed_at - task.created_at).total_seconds() / 3600
                    # Update running average
                    n = metrics.completed_tasks
                    old_avg = metrics.avg_completion_time_hours
                    metrics.avg_completion_time_hours = ((old_avg * (n - 1)) + delta) / n

    def add_message(self, message: Message):
        with self._lock:
            self.messages.append(message)

    def add_feedback(self, user_id: str, rating: float):
        if not (1.0 <= rating <= 5.0):
            raise ValueError("Rating must be between 1.0 and 5.0")
        with self._lock:
            metrics = self._get_or_create_metrics(user_id)
            metrics.feedback_ratings.append(rating)

    def get_user_tasks(self, user_id: str) -> List[Task]:
        with self._lock:
            return [t for t in self.tasks.values() if t.assignee_id == user_id]

    def get_project_tasks(self, project_id: str) -> List[Task]:
        with self._lock:
            return [t for t in self.tasks.values() if t.project_id == project_id]

    def get_project_messages(self, project_id: str) -> List[Message]:
        with self._lock:
            return [m for m in self.messages if m.project_id == project_id]

